import{_ as e,o,c as d,a3 as t}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"工具链结构","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"工具链结构 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/toolchain"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/toolchain"}]]},"headers":[],"relativePath":"zh/xclang/design/toolchain.md","filePath":"zh/xclang/design/toolchain.md","lastUpdated":1794509097000}'),l={name:"zh/xclang/design/toolchain.md"};function a(i,c,n,r,s,g){return o(),d("div",null,[...c[0]||(c[0]=[t('<h1 id="工具链结构" tabindex="-1">工具链结构 <a class="header-anchor" href="#工具链结构" aria-label="Permalink to &quot;工具链结构&quot;">​</a></h1><p><code>clang</code> 通过 <code>bin/</code> 下的纯文本配置文件定位各个目标平台的 sysroot、头文件、运行时库和链接器，而非将默认路径编译进编译器内部。<code>clang</code>、<code>lld</code> 与绝大多数二进制工具共用同一个多合一可执行文件（<code>llvm</code>），而 sysroot 与共用头文件均为普通目录，在 Windows 工具链和 Linux sysroot 中都不包含任何符号链接。因此，本机编译与交叉编译的唯一区别在于是否传入 <code>--target=&lt;triple&gt;</code>，传入 <code>-stdlib=platform</code> 即可切换到平台的 C++ 标准库，传入 <code>--no-default-config</code> 则恢复为上游原版 <code>clang</code>（<a href="./../guide/cross-compiling#how-clang-finds-a-target-s-files">交叉编译</a>、<a href="./../reference/layout">压缩包目录结构</a>）。</p><h2 id="每个目标平台独立的配置文件" tabindex="-1">每个目标平台独立的配置文件 <a class="header-anchor" href="#每个目标平台独立的配置文件" aria-label="Permalink to &quot;每个目标平台独立的配置文件&quot;">​</a></h2><p>为某个目标平台编译或链接时，<code>clang</code> 会在自身可执行文件所在的 <code>bin/</code> 目录下查找 <code>&lt;triple&gt;.cfg</code>（<code>clang-cl</code> 则查找 <code>&lt;triple&gt;-clang-cl.cfg</code>），并将文件中的参数加到命令行最前面。例如传入 <code>--target=aarch64-w64-mingw32</code> 时，<code>clang</code> 会先规范化 triple，再读取 <code>aarch64-w64-windows-gnu.cfg</code>。<code>toolchain/common.ts</code> 会为每个目标平台的所有受支持写法在 <code>bin/</code> 下生成对应的配置文件：</p><table tabindex="0"><thead><tr><th>目标平台</th><th><code>bin/</code> 下的配置文件</th></tr></thead><tbody><tr><td>Linux（glibc）</td><td><code>&lt;arch&gt;-unknown-linux-gnu.cfg</code>, <code>&lt;arch&gt;-pc-linux-gnu.cfg</code></td></tr><tr><td>Linux（musl）</td><td><code>&lt;arch&gt;-unknown-linux-musl.cfg</code>, <code>&lt;arch&gt;-pc-linux-musl.cfg</code></td></tr><tr><td>Windows（MinGW）</td><td><code>&lt;arch&gt;-w64-windows-gnu.cfg</code>, <code>&lt;arch&gt;-pc-windows-gnu.cfg</code></td></tr><tr><td>macOS</td><td><code>&lt;arch&gt;-apple-darwin.cfg</code>, <code>&lt;arch&gt;-apple-macos.cfg</code>, <code>&lt;arch&gt;-apple-macosx.cfg</code></td></tr><tr><td>Windows（MSVC）</td><td><code>&lt;arch&gt;-pc-windows-msvc.cfg</code>、<code>&lt;arch&gt;-unknown-windows-msvc.cfg</code>，以及供 <code>clang-cl</code> 使用的 <code>&lt;spelling&gt;-clang-cl.cfg</code></td></tr></tbody></table><p>其中 <code>&lt;arch&gt;</code> 为 <code>x86_64</code>，或在 64 位 Arm 上同时提供 <code>aarch64</code> 与 <code>arm64</code>。由于 <code>compiler-rt</code> 将库文件安装在规范命名的 <code>&lt;arch&gt;-unknown-linux-*</code> 与 <code>&lt;arch&gt;-w64-windows-gnu</code> 目录下，<a href="./../reference/patches">补丁 0013</a> 会将 Linux 与 MinGW 目标平台的 <code>-pc-</code> 和 <code>arm64-</code> 写法映射回对应的运行时库目录。</p><p>各个目标平台配置文件设置的选项如下（<a href="https://github.com/clice-io/xclang/tree/main/toolchain/config" target="_blank" rel="noreferrer"><code>toolchain/config/</code></a>）：</p><table tabindex="0"><thead><tr><th>目标平台</th><th><code>&lt;spelling&gt;.cfg</code> 中的选项</th></tr></thead><tbody><tr><td>Linux（glibc）</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>、引入目标平台 <code>__config_site</code> 与共用 <code>libc++</code> 头文件的 <code>-stdlib++-isystem</code>、<code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>、<code>-static-libstdc++ -static-libgcc</code>、<code>-fuse-ld=lld</code></td></tr><tr><td>Linux（musl）</td><td>同上，将 <code>-static-libstdc++ -static-libgcc</code> 替换为 <code>-static</code>，连同 <code>musl</code> 一起静态链接（<a href="./../guide/cross-compiling#musl-targets">musl 目标平台</a>）</td></tr><tr><td>Windows（MinGW）</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>、引入目标平台 <code>__config_site</code> 与共用 <code>libc++</code> 头文件的 <code>-stdlib++-isystem</code>、<code>-idirafter &lt;CFGDIR&gt;/../mingw-w64/include</code>、<code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>、<code>-fuse-ld=lld</code>（sysroot 仅含静态库）</td></tr><tr><td>macOS</td><td>在 Linux 与 Windows 主机上设置 <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>（在 macOS 主机上使用 Xcode 的 SDK）；<code>-mmacos-version-min=13.0</code>、<code>-fuse-ld=lld</code>；引入目标平台 <code>__config_site</code> 与共用 <code>libc++</code> 头文件的 <code>-stdlib++-isystem</code>、将 <code>libc++.a</code> 排在 SDK 的 <code>libc++.tbd</code> 之前的 <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code>，以及供查找 <code>libc++.modules.json</code> 的 <code>-B&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code>（<a href="./macos">macOS</a>）</td></tr><tr><td>Windows（MSVC）</td><td>在 Linux 与 macOS 主机上设置 <code>-Xmicrosoft-windows-sys-root &lt;CFGDIR&gt;/../sdk/windows</code>（在 <code>clang-cl</code> 中为 <code>/winsysroot</code>）；<code>@&lt;triple&gt;-sdk.cfg</code>（<code>@&lt;triple&gt;-clang-cl-sdk.cfg</code>），由 <code>xclang sdk</code> 改写以引入当前启用 SDK 的版本配置；<code>-fuse-ld=lld</code>；指定 <code>clang_rt.builtins-&lt;arch&gt;.lib</code> 与混合 CRT 的目标文件指令（<code>--linker-option=/nodefaultlib:libucrt.lib</code>、<code>--dependent-lib=ucrt.lib</code>）；<code>-D_STATIC_INLINE_UCRT_FUNCTIONS=0</code>；以及引入 <code>libc++</code> 的 <code>-stdlib++-isystem</code>（在 <code>clang-cl</code> 中为 <code>/clang:-stdlib++-isystem</code>，编译 C 代码时的告警由<a href="./../reference/patches">补丁 0011</a> 消除；见 <a href="./windows#config-files-and-object-directives">Windows</a>）</td></tr></tbody></table><p><code>&lt;CFGDIR&gt;</code> 会展开为 <code>bin/</code>，因此工具链解压到任意目录均可直接使用，无需修改任何文件。由于 <code>clang</code> 对主机的默认目标平台同样会加载配置文件，在 Linux 上运行本机编译命令 <code>clang++ main.cpp</code> 时，也会基于内置的 glibc 2.17 sysroot 编译并静态链接 <code>libc++</code>。</p><p>另外两条配置文件规则避免了在 <code>clang-cl</code> 与 Bazel 中出现意外行为：</p><ul><li><strong><code>clang-cl</code> 默认构建当前主机架构的 MSVC 目标平台。</strong> 在未传入 <code>--target</code> 的情况下运行时，<code>clang-cl</code> 会先查找 <code>&lt;default-target&gt;-clang-cl.cfg</code> 与 <code>&lt;default-target&gt;.cfg</code>，随后才切换到 MSVC triple。为此，<code>toolchain/common.ts</code> 将 <code>&lt;arch&gt;</code> 对应的 MSVC <code>clang-cl</code> 配置写入了所有目标平台写法的 <code>&lt;spelling&gt;-clang-cl.cfg</code>（以及 <code>&lt;spelling&gt;-clang-cl-system.cfg</code>），使直接运行 <code>clang-cl</code> 时构建 <code>&lt;arch&gt;-pc-windows-msvc</code>，而不会误读主机目标平台的 GNU 风格参数。</li><li><strong>Bazel 将配置文件改写为相对路径。</strong> <code>clang</code> 会把 <code>&lt;CFGDIR&gt;</code> 展开为绝对路径并写入 <code>.d</code> 依赖文件，破坏跨机器的动作缓存命中。因此 Bazel 模块会在 <code>cfg/</code> 下生成使用相对于执行根目录路径的配置文件副本，并在编译时传入 <code>--no-default-config --config=&lt;file&gt;</code>（<a href="./bazel-module#no-absolute-paths">无绝对路径</a>）。</li></ul><h3 id="平台的-c-标准库" tabindex="-1">平台的 C++ 标准库 <a class="header-anchor" href="#平台的-c-标准库" aria-label="Permalink to &quot;平台的 C++ 标准库&quot;">​</a></h3><p>每个 <code>&lt;spelling&gt;.cfg</code> 旁都配有一个 <code>&lt;spelling&gt;-system.cfg</code>（以及 <code>&lt;spelling&gt;-clang-cl-system.cfg</code>）。当传入 <code>libc++</code> 以外的任何 <code>-stdlib=</code> 值（如 <code>-stdlib=platform</code> 或 <code>-stdlib=libstdc++</code>；在 <code>clang-cl</code> 中为 <code>/clang:-stdlib=platform</code>）时，编译器会选用 <code>&lt;spelling&gt;-system.cfg</code> 替代 <code>&lt;spelling&gt;.cfg</code>（<a href="./../reference/patches">补丁 0018</a>、<a href="./../guide/cross-compiling#the-platform-s-c-library">交叉编译</a>）：</p><table tabindex="0"><thead><tr><th>目标平台</th><th><code>&lt;spelling&gt;-system.cfg</code> 中的选项</th></tr></thead><tbody><tr><td>Linux（glibc）、Linux（musl）、Windows（MinGW）</td><td>仅含 <code>-fuse-ld=lld</code>；C 与 C++ 标准库取自宿主机、发行版的交叉编译软件包或 <code>--sysroot</code></td></tr><tr><td>macOS</td><td>SDK 路径（在 Linux 与 Windows 主机上为 <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>）、<code>-mmacos-version-min=13.0</code>、<code>-fuse-ld=lld</code>，并链接 SDK 中的 <code>libc++.tbd</code></td></tr><tr><td>Windows（MSVC）</td><td>去掉了 <code>-stdlib++-isystem</code> 的 MSVC 目标平台配置，使用已下载 SDK 或 Visual Studio 中的微软 STL</td></tr></tbody></table><p>之所以必须切换配置文件，是因为 <code>&lt;spelling&gt;.cfg</code> 中的参数无法在命令行后半部分撤销：无论 <code>-stdlib=</code> 如何设置，<code>-stdlib++-isystem</code> 都会添加 <code>libc++</code> 头文件；macOS 上的 <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> 会把静态库 <code>libc++.a</code> 排在 SDK 的 <code>libc++.tbd</code> 之前；而且内置的 Linux 与 MinGW sysroot 并不包含 <code>libstdc++</code>。</p><h3 id="为什么不把默认配置编译进驱动" tabindex="-1">为什么不把默认配置编译进驱动 <a class="header-anchor" href="#为什么不把默认配置编译进驱动" aria-label="Permalink to &quot;为什么不把默认配置编译进驱动&quot;">​</a></h3><p>LLVM 支持将默认 C++ 标准库、编译器运行时库、栈展开库和链接器直接编译进驱动中（<code>CLANG_DEFAULT_CXX_STDLIB</code>、<code>CLANG_DEFAULT_RTLIB</code>、<code>CLANG_DEFAULT_UNWINDLIB</code>、<code>CLANG_DEFAULT_LINKER</code>），xclang 23.1.2.1 曾采用这种做法。这些设置会被编译进同时属于 <code>libclang</code> 的 <code>clangDriver</code> 库中。</p><p>基于 <code>libclang</code> 构建的工具（如 clice）会运行 <code>clangDriver</code>，根据 <code>compile_commands.json</code> 中其他编译器的条目计算头文件搜索路径。将默认配置编译进 <code>clangDriver</code> 后，编译数据库中的 <code>g++</code> 命令算出的不再是 <code>libstdc++</code> 的头文件路径，而是变成了 xclang 的 <code>libc++</code> 头文件路径。</p><p>不在 <code>toolchain/cmake/caches/clang.cmake</code> 中设置这些 <code>CLANG_DEFAULT_*</code> 变量，而是将默认配置放在 <code>bin/*.cfg</code> 中，即可将两者解耦：<code>bin/clang</code> 会读取 <code>bin/&lt;triple&gt;.cfg</code>，而链接进 <code>libclang</code> 工具内部的 <code>clangDriver</code> 旁没有 <code>bin/*.cfg</code>，行为与上游原版 <code>clang</code> 一致。</p><h3 id="原生无配置编译器" tabindex="-1">原生无配置编译器 <a class="header-anchor" href="#原生无配置编译器" aria-label="Permalink to &quot;原生无配置编译器&quot;">​</a></h3><p>传入 <code>--no-default-config</code> 会指示 <code>clang</code> 忽略 <code>bin/&lt;triple&gt;.cfg</code>。此时 <code>clang</code> 会像未加特殊配置的上游构建一样，查找宿主机系统的头文件和库并调用系统链接器（<code>toolchain/sysroot.ts</code> 与 <code>toolchain/runtimes.ts</code> 在构建 sysroot 和 <code>libc++</code> 本身时就使用了 <code>--no-default-config</code>）。</p><h2 id="多合一可执行文件" tabindex="-1">多合一可执行文件 <a class="header-anchor" href="#多合一可执行文件" aria-label="Permalink to &quot;多合一可执行文件&quot;">​</a></h2><p><code>toolchain/cmake/caches/clang.cmake</code> 开启了 <code>LLVM_TOOL_LLVM_DRIVER_BUILD=ON</code>，将 <code>clang</code>、<code>clang-scan-deps</code>、<code>lld</code> 以及绝大多数二进制工具（<code>llvm-ar</code>、<code>llvm-ranlib</code>、<code>llvm-lib</code>、<code>llvm-dlltool</code>、<code>llvm-nm</code>、<code>llvm-objcopy</code>、<code>llvm-strip</code>、<code>llvm-install-name-tool</code>、<code>llvm-objdump</code>、<code>llvm-readobj</code>、<code>llvm-rc</code>、<code>llvm-windres</code>、<code>llvm-symbolizer</code>、<code>dsymutil</code>、<code>llvm-gsymutil</code>、<code>llvm-libtool-darwin</code>、<code>llvm-lipo</code> 等）合并构建为单个多合一可执行文件 <code>bin/llvm</code>（在 Windows 上为 <code>bin/llvm.exe</code>）。</p><p>这样无需在每个工具中重复打包一份 LLVM 库：<code>bin/</code> 下的各个工具名在 Linux 与 macOS 上是指向 <code>llvm</code> 的符号链接，在 Windows 上则是由 <a href="https://github.com/clice-io/xclang/blob/main/toolchain/launcher/alias.c" target="_blank" rel="noreferrer"><code>toolchain/launcher/alias.c</code></a> 编译而成的轻量启动器，负责在配置了关闭即终止的作业对象内启动 <code>llvm.exe &lt;tool-name&gt; &lt;arguments&gt;</code>（<a href="./windows#the-launchers">启动器</a>）。配合省略 glibc 的 <code>locale-archive</code>、链接时开启安全相同代码折叠（Linux 与 Windows 上传入 <code>-Wl,--icf=safe -Wl,-O2</code>）以及使用 <code>.tar.xz</code> 压缩所有主机压缩包，每个主机工具链压缩包的体积都控制在 100 MB 左右（<a href="./../reference/releases#assets">版本发布</a>）。</p><p>让各个工具动态链接共享库 <code>libLLVM</code>（<code>LLVM_LINK_LLVM_DYLIB</code>）虽然也能共享代码，但出于编译速度考量未采用：跨共享库边界的调用必须经过动态链接器跳表，而且 ThinLTO 无法跨共享库边界内联和优化。</p><p>LLVM 多合一驱动构建未包含的五个工具则在 <code>bin/</code> 下编译为独立的可执行文件：<code>llvm-profdata</code>、<code>llvm-cov</code>、<code>llvm-dwarfdump</code>、<code>llvm-strings</code> 与 <code>FileCheck</code>。</p><h3 id="的输出格式" tabindex="-1"><code>-###</code> 的输出格式 <a class="header-anchor" href="#的输出格式" aria-label="Permalink to &quot;`-###` 的输出格式&quot;">​</a></h3><p>由于 <code>clang</code> 由多合一程序 <code>llvm</code> 分发执行，<code>clang -###</code> 打印的 <code>-cc1</code> 命令会以 <code>llvm</code> 作为可执行文件名，并在 <code>&quot;-cc1&quot;</code> 之前多出一个 <code>&quot;clang&quot;</code> 参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/path/xclang/bin/llvm&quot; &quot;clang&quot; &quot;-cc1&quot; ...</span></span></code></pre></div><p>解析 <code>clang -###</code> 输出的工具应向后扫描查找 <code>&quot;-cc1&quot;</code>，而不要假定可执行文件路径后的第一个参数就是 <code>&quot;-cc1&quot;</code>。</p><h2 id="纯目录结构" tabindex="-1">纯目录结构 <a class="header-anchor" href="#纯目录结构" aria-label="Permalink to &quot;纯目录结构&quot;">​</a></h2><p>每个目标平台的 sysroot（<code>&lt;toolchain&gt;/&lt;triple&gt;/</code>）都是一个只包含编译和链接所需文件的普通目录：头文件、启动文件、C 运行时库、<code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code> 与 <a href="./hermeticity#gcc-library-names">GCC 桩库</a>，而 <code>compiler-rt</code> 则存放在 <code>lib/clang/&lt;major&gt;/lib/</code> 下（<a href="./../reference/layout">压缩包目录结构</a>）。</p><p>在多个目标平台之间完全相同的头文件只存放一份，且不使用符号链接（由 <code>toolchain/common.ts</code> 中的 <code>shareHeaders</code> 处理）：所有目标平台共用 <code>libc++/include/c++/v1</code>，各目标平台的 <code>__config_site</code>（以及非 MSVC 目标平台上的 <code>cxxabi.h</code>）放在 <code>libc++/include/&lt;normalized-triple&gt;/c++/v1</code> 下，两个 MinGW 目标平台则共用 <code>mingw-w64/include</code>（<a href="./../reference/layout#shared-headers">共用头文件</a>）。<code>toolchain/package.ts</code> 会校验 Windows 工具链压缩包不含任何符号链接，且所有压缩包中都不存在仅大小写不同的两个路径（<a href="./hermeticity#why-glibc-2-17">为什么选择 glibc 2.17</a>）。</p><p>各 sysroot 与 <code>compiler-rt</code> 目录中的内容并不绑定于 xclang 编译的 <code>clang</code>。只要传入 <code>--sysroot</code> 与 <code>-resource-dir</code>，任何同主版本号的上游 <code>clang</code> 都可以基于这些目标平台目录执行交叉编译。</p>',34)])])}const m=e(l,[["render",a]]);export{p as __pageData,m as default};
